	private static void assertCase(MatrixCase testCase) {
		List<Executable> executions = List.of(false, true)
				.stream()
				.map(exactStatistics -> (Executable) () -> runCase(testCase, exactStatistics))
				.toList();
		assertAll(testCase.name(), executions);
	}

	private static void runCase(MatrixCase testCase, boolean exactStatistics) throws QueryEvaluationException {
		FiniteTripleSource source = new FiniteTripleSource(testCase.statements());
		List<BindingSet> expected = testCase.expected();
		List<BindingSet> raw = evaluate(parse(testCase.query()).getTupleExpr(), source);
		assertThat(raw)
				.as("raw result for %s with %s", testCase.name(), exactStatistics ? "exact" : "standard")
				.containsExactlyInAnyOrderElementsOf(expected);

		ParsedTupleQuery parsed = parse(testCase.query());
		QueryRoot root = new QueryRoot(parsed.getTupleExpr());
		EvaluationStatistics statistics = exactStatistics ? new ExactDatasetStatistics(source)
				: new EvaluationStatistics();
		new QueryJoinOptimizer(statistics, source).optimize(root, null, EmptyBindingSet.getInstance());

		List<BindingSet> optimized = evaluate(root, source);
		assertThat(optimized)
				.as("optimized result for %s with %s", testCase.name(), exactStatistics ? "exact" : "standard")
				.containsExactlyInAnyOrderElementsOf(expected);
		assertThat(optimized)
				.as("optimized/raw result bag for %s with %s", testCase.name(), exactStatistics ? "exact" : "standard")
				.containsExactlyInAnyOrderElementsOf(raw);
	}

	private static ParsedTupleQuery parse(String query) {
		return QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null);
	}

	private static List<BindingSet> evaluate(TupleExpr expression, TripleSource source)
			throws QueryEvaluationException {
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null);
		List<BindingSet> results = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.evaluate(expression, EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				results.add(iteration.next());
			}
		}
		return results;
	}

	private static BindingSet row(Object... entries) {
		MapBindingSet bindingSet = new MapBindingSet();
		for (int i = 0; i < entries.length; i += 2) {
			bindingSet.addBinding((String) entries[i], (Value) entries[i + 1]);
		}
		return bindingSet;
	}

	private static IRI iri(String value) {
		return VF.createIRI(value);
	}

	private static Value literal(String value) {
		return VF.createLiteral(value);
	}

	private static Value integer(int value) {
		return VF.createLiteral(Integer.toString(value), XSD.INTEGER);
	}

	private static Statement statement(String subject, String predicate, String object) {
		return VF.createStatement(iri(subject), iri(predicate), iri(object));
	}

	private static Statement literalStatement(String subject, String predicate, String object) {
		return VF.createStatement(iri(subject), iri(predicate), literal(object));
	}

	private record MatrixCase(String name, String query, List<Statement> statements, List<BindingSet> expected) {
		private MatrixCase {
			statements = List.copyOf(statements);
			expected = List.copyOf(expected);
		}
	}

	private static final class ExactDatasetStatistics extends EvaluationStatistics {
		private final TripleSource source;

		private ExactDatasetStatistics(TripleSource source) {
			this.source = source;
		}

		@Override
		public boolean supportsJoinEstimation() {
			return true;
		}

		@Override
		public double getCardinality(TupleExpr expression) {
			try {
				return evaluate(expression, source).size();
			} catch (QueryEvaluationException e) {
				throw new IllegalStateException("finite fixture cardinality evaluation failed", e);
			}
		}
	}

	private static final class FiniteTripleSource implements TripleSource {
		private final List<Statement> statements;

		private FiniteTripleSource(List<Statement> statements) {
			this.statements = statements;
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			return new CloseableIteratorIteration<>(statements.stream()
					.filter(statement -> subj == null || subj.equals(statement.getSubject()))
					.filter(statement -> pred == null || pred.equals(statement.getPredicate()))
					.filter(statement -> obj == null || obj.equals(statement.getObject()))
					.iterator());
		}

		@Override
		public Set<StatementOrder> getSupportedOrders(Resource subj, IRI pred, Value obj, Resource... contexts)
				throws QueryEvaluationException {
			return Set.of();
		}

		@Override
		public ValueFactory getValueFactory() {
			return VF;
		}

		@Override
		public Comparator<Value> getComparator() {
			return null;
		}
	}
